// Calculate number of groups needed (each group is 1 byte = 8 bits)
    size_t ngroups = (nbits + 7) >> 3;  // Equivalent to (nbits + 7) / 8

    // Initialize bitmap_info_t structure
    binfo->nbits = nbits;
    binfo->ngroups = ngroups;
    binfo->bitmap = static_cast<unsigned char*>(std::malloc(ngroups));
    if (binfo->bitmap == nullptr) {
        std::abort();  // Allocation failure
    }

    // Initialize all bits to 0
    std::memset(binfo->bitmap, 0, ngroups);

